package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/golang/avro/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the Go source code
	fileBytes, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", sourceFile, err)
		os.Exit(1)
	}
	src := string(fileBytes)

	// Parse the source code into an AST (Abstract Syntax Tree)
	fset := token.NewFileSet()
	ast.Parse(fset, src)

	// Find all declarations with the specified struct name
	var structs []schema.StructDef
	for _, decl := range fset.Decls {
		if ast.IsExported(decl.Name) && decl.Tok == token.TYPE {
			node := decl.(*ast.TypeSpec).Type.(*ast.StructType)
			if node.Fields.List != nil {
				for i := range node.Fields.List {
					field := node.Fields.List[i].(*ast.Field)
					if field.Names != nil {
						if field.Names[0].Name.Value == structName {
							structs = append(structs, schema.NewStructDef(node.Name, field.Names))
						}
					}
				}
			}
		}
	}

	// Write the Avro schema to a file
	if len(structs) > 0 {
		outfile := fmt.Sprintf("%s.avsc", structName)
		err = ioutil.WriteFile(outfile, []byte(schema.StringifySchema(&structs[0])), 0644)
		if err != nil {
			fmt.Printf("Failed to write Avro schema to %s: %v\n", outfile, err)
			os.Exit(1)
		}
	} else {
		fmt.Printf("No struct found with name '%s' in %s.\n", structName, sourceFile)
		os.Exit(1)
	}
}
